import React from 'react';
import { useLocation } from 'react-router-dom';

const Profile = () => {
  const location = useLocation();
  const { item, role } = location.state || {}; // Access the passed item and role

  console.log('Profile data:', item, role); // For debugging - remove later

  return (
    <div style={{ textAlign: 'center', marginTop: '50px' }}>
      <h1 style={{ fontSize: '5em', fontWeight: 'bold' }}>Hello</h1>
      {/* You can add more content here later, e.g., display item details */}
    </div>
  );
};

export default Profile;
